gacH(){return"\u0633\u062c\u0644 \u0627\u0644\u0645\u0637\u0627\u0644\u0628\u0627\u062a\u060c \u0627\u0644\u062d\u0632\u0645\u060c \u0627\u0644\u0645\u062a\u063a\u064a\u0631\u0627\u062a\u060c \u0627\u0644\u0642\u0648\u0627\u0644\u0628\u060c \u0627\u0644\u062a\u062d\u0642\u0642\u060c \u0627\u0644\u062a\u0627\u0631\u064a\u062e\u060c \u0627\u0644\u0625\u0635\u062f\u0627\u0631\u0627\u062a\u060c \u0648\u0627\u0644\u062a\u0631\u0627\u062c\u0639."},
