gacE(){return"\u0633\u062c\u0644\u0627\u062a \u0627\u0644\u062a\u0634\u063a\u064a\u0644"},
gacD(){return"\u0623\u0633\u0633 \u0633\u062c\u0644\u0627\u062a \u0627\u0644\u0623\u062d\u062f\u0627\u062b\u060c \u0627\u0644\u0623\u062e\u0637\u0627\u0621\u060c \u0627\u0644\u062a\u062f\u0642\u064a\u0642\u060c \u0627\u0644\u062c\u062f\u0648\u0644 \u0627\u0644\u0632\u0645\u0646\u064a \u0644\u0644\u062a\u0634\u063a\u064a\u0644\u060c \u0648\u0627\u0644\u062a\u0639\u0627\u0641\u064a."},
gaer(){return"\u062a\u0646\u0633\u064a\u0642 \u0627\u0644\u0630\u0643\u0627\u0621"},
gaem(){return"\u0627\u0644\u062c\u064a\u0644 \u0627\u0644\u062b\u0627\u0646\u064a 2.2 - \u0637\u0628\u0642\u0629 \u0627\u0644\u062a\u0646\u0633\u064a\u0642. \u0644\u0627 \u062a\u0646\u0641\u064a\u0630\u060c \u0644\u0627 \u0645\u0632\u0648\u062f\u064a\u0646\u060c \u0644\u0627 \u0623\u062a\u0645\u062a\u0629."},
gaeo(){return"\u0645\u062d\u0631\u0643 \u0627\u0644\u0645\u0647\u0627\u0645"},
