gaed(){return"\u0645\u062d\u0631\u0643 \u0645\u0637\u0627\u0628\u0642\u0629 \u0627\u0644\u0642\u062f\u0631\u0627\u062a"},
gaec(){return"\u0637\u0628\u0642\u0629 \u0627\u0644\u0642\u0631\u0627\u0631 \u0644\u0645\u062f\u0649 \u0645\u0644\u0627\u0621\u0645\u0629 \u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064a\u060c \u062d\u0632\u0645 \u0627\u0644\u0645\u0637\u0627\u0644\u0628\u0627\u062a\u060c \u062d\u0632\u0645 \u0627\u0644\u0645\u0639\u0631\u0641\u0629\u060c \u0627\u0644\u0623\u062f\u0648\u0627\u062a\u060c \u0648\u0645\u0648\u0627\u0641\u0642\u0629 \u0627\u0644\u0645\u0627\u0644\u0643."},
gaef(){return"\u0645\u062d\u0631\u0643 \u0627\u0644\u062a\u0628\u0639\u064a\u0627\u062a"},
gaee(){return"\u0631\u0633\u0648\u0645 \u0627\u0644\u062a\u0628\u0639\u064a\u0627\u062a \u0644\u0648\u0642\u062a \u0627\u0644\u062a\u0634\u063a\u064a\u0644 \u0644\u0644\u0645\u0647\u0627\u0645\u060c \u0627\u0644\u062d\u0632\u0645\u060c \u0627\u0644\u0623\u0635\u0648\u0644\u060c \u0627\u0644\u0645\u0634\u0627\u0631\u064a\u0639\u060c \u0627\u0644\u0633\u062c\u0644\u0627\u062a\u060c \u0627\u0644\u062a\u0642\u0627\u0631\u064a\u0631\u060c \u0627\u0644\u0643\u0631\u0648\u062a\u060c \u0648\u0627\u0644\u0623\u062f\u0644\u0629."},
gaej(){return"\u0645\u062f\u064a\u0631 \u0632\u0645\u0627\u0645 \u0627\u0644\u0639\u0645\u0644"},
